{
  "title": "The Glass Diver's Escape",
  "gate_token": "WDWObX-PrlBzPs69YEqoOw",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver arrives at the ruined city gates.",
      "visual_description": "A crumbling stone gate topped with old royal banners, torn and faded. The glass diver stands before it, his diving helmet reflecting the shattered cityscape.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the cartographer unfolds a map outside the walls.",
      "visual_description": "Mara kneels on the ground, unrolling a stained parchment map. The tin fox sits beside her, blue eyes glowing. The gate looms in the background.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp gives a first warning from a broken window.",
      "visual_description": "The oracle lamp sits on a windowsill, its flame eye glowing. It flickers as it speaks, and the glass diver listens from below.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "The sleeping tax collector blocks a narrow alley.",
      "visual_description": "The sleeping tax collector snores with a ledger under his head. Stamped papers flutter from his sleeves. Mara steps carefully around him.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The tin fox scouts ahead to a cursed tower.",
      "visual_description": "The tin fox sneaks toward a twisted stone tower covered in thorny vines. Its key-wind tail clicks with each step.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Mara reads a hidden symbol on a wall.",
      "visual_description": "Mara presses her compass against a mossy wall, revealing a faint glowing symbol. The glass diver watches from behind a fallen pillar.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "The oracle lamp warns of an invisible trap.",
      "visual_description": "The oracle lamp sits on a cobblestone, emitting a smoky crescent shape. The glass diver and tin fox pause before a seemingly empty courtyard.",
      "characters": ["oracle_lamp", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The glass diver swims through a mirror into a locked chamber.",
      "visual_description": "The glass diver presses his helmet against a tall silver mirror, his reflection rippling. He steps through into a dusty room beyond.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "The sleeping tax collector dozes on a pile of rubble.",
      "visual_description": "The sleeping tax collector curls up on broken stones, hugging a ledger. Mara steps over him, shaking her head.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "The tin fox finds a key in a fountain.",
      "visual_description": "The tin fox dips its paw into a dry fountain basin filled with dust. Its blue eyes flash as it retrieves a brass key.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Mara identifies a magic door by its aura.",
      "visual_description": "Mara holds her compass up to a stone door covered in faint runes. The glass diver stands ready with the brass key.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "The oracle lamp guides them past a patrol.",
      "visual_description": "The oracle lamp dims its light, signaling quiet. The glass diver and tin fox crouch behind a wall as armored patrols march by in the distance.",
      "characters": ["oracle_lamp", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The glass diver opens the magic door.",
      "visual_description": "The glass diver inserts the key into the rune-covered door. The runes glow brightly, and the door swings open to reveal a dark corridor.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "Mara finds a hidden passage behind a tapestry.",
      "visual_description": "Mara pulls aside a torn royal banner, revealing a narrow staircase. The oracle lamp hovers nearby, casting a warm glow.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The group reunites in a tower chamber.",
      "visual_description": "The glass diver, Mara, tin fox, and oracle lamp gather in a circular room with a broken window overlooking the ruined city.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "The sleeping tax collector accidentally triggers a bell.",
      "visual_description": "The sleeping tax collector rolls over in his sleep and knocks a bell from a ledge. It clangs loudly, echoing through the streets.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "They race toward the final bridge under pursuit.",
      "visual_description": "The glass diver, Mara, tin fox, and oracle lamp run across a long stone bridge spanning a chasm. Armored patrols follow behind.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "The glass diver shatters the bridge behind them.",
      "visual_description": "At the far end of the bridge, the glass diver thrusts his hand into a reflection in the stone, causing the bridge to crack and collapse. The group escapes as the ruined city recedes.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

